<?php
declare(strict_types=1);require_once __DIR__.'/../config/agency_auth.php';$u=require_agency();if(empty($_SESSION['agency_csrf']))$_SESSION['agency_csrf']=bin2hex(random_bytes(32));$pdo=db();$message='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['agency_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$property=(int)$_POST['property_id'];$from=$_POST['start_date'];$to=$_POST['end_date'];$discount=($_POST['discount']??'')===''?null:(float)$_POST['discount'];$price=($_POST['price']??'')===''?null:(float)$_POST['price'];if(!$property||!$from||!$to||$from>$to||($discount===null&&$price===null))throw new RuntimeException('Ürün, tarih ve indirim veya fiyat talebi zorunludur.');$q=$pdo->prepare('SELECT supplier_id FROM properties WHERE id=? AND status=\'active\'');$q->execute([$property]);$supplier=$q->fetchColumn();if(!$supplier)throw new RuntimeException('Ürün satışa açık değil.');$pdo->prepare('INSERT INTO agency_discount_requests(agency_id,supplier_id,property_id,start_date,end_date,requested_discount_percent,requested_price,currency,message) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$u['agency_id'],$supplier,$property,$from,$to,$discount,$price,$_POST['currency']??'EUR',trim((string)$_POST['message'])]);$message='Talebiniz tedarikçiye iletildi.';}}catch(Throwable $e){$error=$e->getMessage();}$products=$pdo->query("SELECT p.id,p.name,p.city,s.company_name FROM properties p JOIN suppliers s ON s.id=p.supplier_id WHERE p.status='active' AND s.status IN ('active','pilot') ORDER BY p.name")->fetchAll();$q=$pdo->prepare('SELECT r.*,p.name property_name,s.company_name FROM agency_discount_requests r JOIN properties p ON p.id=r.property_id JOIN suppliers s ON s.id=r.supplier_id WHERE r.agency_id=? ORDER BY r.id DESC');$q->execute([$u['agency_id']]);$rows=$q->fetchAll();?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>İndirim talepleri</title><style>body{font-family:Arial;background:#f7f7f2;margin:0}.w{width:min(1000px,calc(100% - 32px));margin:35px auto}.c{background:#fff;border:1px solid #ddd;padding:18px;margin:15px 0}.r{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}input,select,textarea,button{padding:9px;font:inherit}.ok{background:#e6f8c7;padding:9px}.er{background:#ffe2de;padding:9px}@media(max-width:700px){.r{grid-template-columns:1fr}}</style></head><body><main class="w"><a href="/nexustraveltech/acente/">← Panel</a><h1>Özel fiyat ve indirim talebi</h1><?php if($message):?><p class="ok"><?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="er"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" class="c"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['agency_csrf'])?>"><div class="r"><select name="property_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'].' · '.$p['company_name'])?></option><?php endforeach;?></select><input type="date" name="start_date" required><input type="date" name="end_date" required></div><div class="r"><input type="number" step="0.01" name="discount" placeholder="Talep edilen indirim %"><input type="number" step="0.01" name="price" placeholder="veya hedef fiyat"><select name="currency"><option>EUR</option><option>TRY</option><option>USD</option><option>GBP</option></select></div><textarea name="message" placeholder="Tedarikçiye notunuz"></textarea><button>Talebi gönder</button></form><?php foreach($rows as $r):?><article class="c"><b><?=htmlspecialchars($r['property_name'])?></b> · <?=htmlspecialchars($r['company_name'])?><p><?=htmlspecialchars($r['start_date'])?> / <?=htmlspecialchars($r['end_date'])?> · indirim <?=htmlspecialchars($r['requested_discount_percent']??'—')?>% · hedef <?=htmlspecialchars($r['requested_price']??'—')?> <?=htmlspecialchars($r['currency']??'')?></p><strong><?=htmlspecialchars($r['status'])?></strong></article><?php endforeach;?></main></body></html>
